INSERT INTO revisions (dissertation_id,revision_code,title,revision_type,source_filename,content_sha256,status,notes) VALUES (@k1_d,'K1_A2_UPDATE_V3_2026-11-09','Anlage 1A.2 – Iterativer Aufbau einer linearen Funktion (aktualisierte Autorenvorlage)','EDIT','FRZK_Kapitel1_Anlage_A2_aktualisiert_v3_2026-11-09.docx','918aef913ed44c2ae0b783146e7b766de1d9c977272c56056b4cbd2693ecb58b','OPEN','Aktualisierte 7-Bild-Fassung, Steigung 0,9, Funktionsgleichung f(x)=0,9x+5,5. Mathematische und empirische Grenzen offen dokumentiert.') ON DUPLICATE KEY UPDATE title=VALUES(title),source_filename=VALUES(source_filename),content_sha256=VALUES(content_sha256),notes=VALUES(notes);
INSERT INTO sections (chapter_id,parent_section_id,section_number,title,level_no,sort_order,body_text,scientific_status,status,current_revision_id,content_sha256) VALUES (@k1_c,NULL,'1.A2','Anlage 1A.2 – Iterativer Aufbau einer linearen Funktion (aktualisierte Autorenvorlage)',1,950,'Die aktualisierte Autorenvorlage „A.2 lineareFunktion_erklärt(3).docx“ dokumentiert in sieben aufeinander aufbauenden Grafiken den schrittweisen Zugang zu einer linearen Funktion. Sie ergänzt das Unterrichtsbeispiel aus Abschnitt 1.1.2, ohne eine standardisiert erhobene Lernwirkung zu behaupten. Die grafisch erläuterten Parameter a = 0,9 und b = 5,5 sind Angaben der überarbeiteten Vorlage; die angegebenen Zahlen sind nicht als vermessene Originaldaten einer Schülerbearbeitung belegt. Die neue Erläuterung der Parameter a und b ist Bestandteil der Autorenvorlage. Die nachfolgende Prüfschleife ist eine methodische Erläuterung, keine aus den Bildern belegte Beobachtung eines Rücksprungs.\n\nSchritt 1 – Eigenen Standpunkt markieren\n\nAusgangsimpuls: „Markiere Deinen eigenen Standpunkt“. Das zunächst isolierte Zeichen steht für eine subjektive Ausgangsorientierung. Es ist keine mathematische Definition des Koordinatenursprungs.\n\nA2-1: Ausgangsposition vor dem Aufbau des Bezugssystems. Autorenvorlage.\n\nSchritt 2 – Eine Gerade als Gegenstand darstellen\n\nAusgangsimpuls: „Füge ein Abbild einer linearen Funktion hinzu“. Die Gerade wird sichtbar; ihre Lage, Steigung und ihr Achsenabschnitt sind damit noch nicht numerisch festgelegt.\n\nA2-2: Gerade und markierter Standpunkt. Autorenvorlage.\n\nSchritt 3 – Koordinatensystem hinzufügen\n\nAusgangsimpuls: „Füge ein Bezugssystem hinzu“. Achsen erlauben es, die Lage der Geraden auf eine definierte Darstellung zu beziehen.\n\nA2-3: Ergänzte Koordinatenachsen. Autorenvorlage.\n\nSchritt 4 – Größen den Achsen zuordnen\n\nAusgangsimpuls: „Welche Größen wollen wir für die senkrechten und waagerechten Werte verwenden (x,y)?“ Die horizontale Achse wird mit x, die vertikale mit y bezeichnet. x steht als Eingangsgröße, y als zugeordneter Funktionswert.\n\nA2-4: Bezeichnete x- und y-Achse. Autorenvorlage.\n\nSchritt 5 – Definitionsbereich und Skalierung klären\n\nAusgangsimpuls: „Um die Funktion beschreiben zu können, benötigen wir einen …-Bereich“. Der Definitionsbereich legt zulässige x-Werte fest; Maßstab und Einheiten werden für ein Ablesen zusätzlich benötigt. Die Vorlage wählt gleiche Achsenmaßstäbe. Diese Wahl ist praktisch, aber nicht erforderlich, damit ein Koordinatensystem mathematisch gültig ist.\n\nA2-5: Koordinatensystem mit Skalierung. Autorenvorlage; EMF für die Word-Fassung in PNG übertragen.\n\nSchritt 6 – Die Steigung bestimmen\n\nDie neue Abbildung ergänzt das Steigungsdreieck. Für zwei Punkte der nicht senkrechten Geraden mit Δx ≠ 0 gilt a = Δy/Δx. Die aktuelle Autorenvorlage gibt hierfür näherungsweise a = 0,9 an und schreibt zunächst f(x) = 0,9x + b.\n\nSteigungsregel: a = Δy / Δx, wobei Δx ≠ 0.  Ergebnis der Autorenvorlage: a ≈ 0,9.\n\nWord-LaTeX: a=\\frac{\\Delta y}{\\Delta x},\\quad a\\approx 0{,}9\n\nA2-6: Steigungsdreieck mit Δx und Δy. Autorenvorlage.\n\nSchritt 7 – Den y-Achsenabschnitt bestimmen\n\nDer Schnittpunkt der Geraden mit der y-Achse wird als b = f(0) bezeichnet. Die neue Autorenvorlage gibt b = 5,5 an. Zusammen mit a = 0,9 ergibt sich f(x) = 0,9x + 5,5. Dies ist die in der Vorlage verwendete lineare beziehungsweise affine Funktionsdarstellung.\n\nAllgemeine Form: f(x) = ax + b.  Beispiel der Autorenvorlage: f(x) = 0,9x + 5,5.\n\nWord-LaTeX: f(x)=ax+b,\\quad f(x)=0{,}9x+5{,}5\n\nA2-7: y-Achsenabschnitt b und Steigungsdreieck. Autorenvorlage.\n\nErgänzende Erläuterung der Funktionsparameter (neue Autorenvorlage)\n\nDie Funktionsgleichung f(x)=ax+b beschreibt eine Gerade; die Parameter a und b bestimmen ihre Form und Lage.\n\nHier sind die beiden mathematischen Bausteine kurz zusammengefasst:\n\nDer Anstieg / die Steigung (a): Positives a bedeutet eine steigende, negatives a eine fallende Gerade; bei a=0 verläuft sie waagerecht.\n\nDer y-Achsenabschnitt (b): Die Gerade schneidet die vertikale y-Achse im Punkt (0,b); b beschreibt ihre vertikale Lage beziehungsweise Verschiebung.\n\nSchritt 8 – Eindeutigkeit und Geltungsbereich prüfen\n\nDie Vorlage spricht von „eineindeutiger Zuordnung“. Für den Funktionsbegriff muss jedem x des festgelegten Definitionsbereichs genau ein y-Wert zugeordnet sein. Eine allgemeine Umkehr-Eindeutigkeit ist nicht erforderlich. Bei der hier angegebenen Steigung a = 0,9 ist die konkret dargestellte Funktion auf ℝ allerdings streng monoton und damit injektiv. Die beiden Aussagen sind zu unterscheiden.\n\nSchritt 9 – Iterative Rückprüfung (methodische Ergänzung)\n\nBei Widersprüchen oder fehlenden Angaben kann zu einem früheren Bearbeitungsschritt zurückgekehrt werden: Sind Achsen und Einheiten festgelegt? Ist der Definitionsbereich benannt? Passen a = Δy/Δx und b = f(0) zur Zeichnung? Als Kontrollbeispiel liefert die Funktionsgleichung f(0) = 5,5 und f(1) − f(0) = 0,9. Wenn eine Prüfung misslingt, werden Annahme oder Darstellung angepasst und erneut überprüft. Die aktualisierten sieben Originalgrafiken zeigen den Aufbau; einen tatsächlichen Rücksprung oder Lernerfolg dokumentieren sie nicht.\n\nWissenschaftliche Einordnung. Die Anlage illustriert den methodischen FRZK-Ansatz als strukturierte, potenziell wiederholbare Problemerschließung. Das Verfahren ist hier ohne FRZK-spezifische Grenzwertzeichen und Vektoroperatoren anwendbar. Die in der Vorlage genannten Zahlenwerte sind als grafische Beispielparameter zu behandeln; ihre unabhängige Kalibrierung und die empirische Wirksamkeit gehören nicht zum Nachweisumfang dieser Anlage.','Didaktisches Demonstrationsmaterial; Autorenrevision 09.11.2026; Kontrollschleife als methodische Ergänzung.','REVIEW',@k1_r,'b7fdd94c70edcc1f10a353381d74b8ec3a19f105c1e357d27b1c88a0a712f360') ON DUPLICATE KEY UPDATE title=VALUES(title),body_text=VALUES(body_text),scientific_status=VALUES(scientific_status),current_revision_id=VALUES(current_revision_id),content_sha256=VALUES(content_sha256);
