INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_s,35,'K1-A2-35','Bei Widersprüchen oder fehlenden Angaben kann zu einem früheren Bearbeitungsschritt zurückgekehrt werden: Sind Achsen und Einheiten festgelegt? Ist der Definitionsbereich benannt? Passen a = Δy/Δx und b = f(0) zur Zeichnung? Als Kontrollbeispiel liefert die Funktionsgleichung f(0) = 5,5 und f(1) − f(0) = 0,9. Wenn eine Prüfung misslingt, werden Annahme oder Darstellung angepasst und erneut überprüft. Die aktualisierten sieben Originalgrafiken zeigen den Aufbau; einen tatsächlichen Rücksprung oder Lernerfolg dokumentieren sie nicht.','3286b3369f69ecec7cfec5e0860fba4102e0c90589483e882a0818c58c7e755a',@k1_r);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) VALUES (@k1_s,36,'K1-A2-36','Wissenschaftliche Einordnung. Die Anlage illustriert den methodischen FRZK-Ansatz als strukturierte, potenziell wiederholbare Problemerschließung. Das Verfahren ist hier ohne FRZK-spezifische Grenzwertzeichen und Vektoroperatoren anwendbar. Die in der Vorlage genannten Zahlenwerte sind als grafische Beispielparameter zu behandeln; ihre unabhängige Kalibrierung und die empirische Wirksamkeit gehören nicht zum Nachweisumfang dieser Anlage.','a8710fcfd918ab9fd2056058ac9dbf0dc7a5756d41ed6cd1c1c096b54f0d15b1',@k1_r);
INSERT INTO paragraphs (section_id,paragraph_index,paragraph_label,paragraph_text,content_sha256,created_revision_id) SELECT @k1_112,@k1_next,'K1-A2-VERWEIS','Anlage 1A.2 zeigt ergänzend zur hier beschriebenen Unterrichtsbeobachtung den schrittweisen Aufbau einer linearen Funktion. Die aktualisierte Vorlage führt die Bestimmung von Steigung und y-Achsenabschnitt bis zur Funktionsgleichung f(x) = 0,9x + 5,5 fort. Die Rückprüfung wird als methodische Ergänzung erläutert; ein empirischer Lernerfolg ist damit nicht nachgewiesen.','c9260c2e2ef377c03b7e0dcac423bc257b837d54fb6dba5113c0d6e32e319993',@k1_r FROM DUAL WHERE @k1_link_id IS NULL;
INSERT INTO research_objects (dissertation_id,chapter_id,section_id,object_type,object_code,title,sort_order,status,created_revision_id,notes) VALUES (@k1_d,@k1_c,@k1_s,'FIGURE','K1_A2_F01','A2-1: Ausgangsposition vor dem Aufbau des Bezugssystems. Autorenvorlage.',1,'REVIEW',@k1_r,'Bild aus aktualisierter Autorenvorlage') ON DUPLICATE KEY UPDATE section_id=VALUES(section_id),title=VALUES(title),created_revision_id=VALUES(created_revision_id);
INSERT INTO figures (object_id,figure_number,title,figure_type,caption,description,provenance_type,provenance_notes,rights_status,validation_status,notes) VALUES (@k1_o,'A1A2.1','A2-1: Ausgangsposition vor dem Aufbau des Bezugssystems. Autorenvorlage.','DIAGRAM','A2-1: Ausgangsposition vor dem Aufbau des Bezugssystems. Autorenvorlage.','Ausgangsimpuls: „Markiere Deinen eigenen Standpunkt“. Das zunächst isolierte Zeichen steht für eine subjektive Ausgangsorientierung. Es ist keine mathematische Definition des Koordinatenursprungs.','OWN','Aus der aktualisierten Vorlage A.2 lineareFunktion_erklärt(3).docx, Quelle SHA256 91283a6214ec3891f95ae71fd753adf57661cbb84a800abf732996e401e700b8','UNCLEAR','OPEN','Rechte der verwendeten grafischen Elemente gesondert prüfen') ON DUPLICATE KEY UPDATE title=VALUES(title),caption=VALUES(caption),description=VALUES(description),provenance_notes=VALUES(provenance_notes);
