INSERT INTO figures (object_id,figure_number,title,figure_type,caption,description,provenance_type,provenance_notes,rights_status,validation_status,notes) VALUES (@k1_o,'A1A2.3','A2-3: Ergänzte Koordinatenachsen. Autorenvorlage.','DIAGRAM','A2-3: Ergänzte Koordinatenachsen. Autorenvorlage.','Ausgangsimpuls: „Füge ein Bezugssystem hinzu“. Achsen erlauben es, die Lage der Geraden auf eine definierte Darstellung zu beziehen.','OWN','Aus der aktualisierten Vorlage A.2 lineareFunktion_erklärt(3).docx, Quelle SHA256 91283a6214ec3891f95ae71fd753adf57661cbb84a800abf732996e401e700b8','UNCLEAR','OPEN','Rechte der verwendeten grafischen Elemente gesondert prüfen') ON DUPLICATE KEY UPDATE title=VALUES(title),caption=VALUES(caption),description=VALUES(description),provenance_notes=VALUES(provenance_notes);
