INSERT INTO research_objects (dissertation_id,chapter_id,section_id,object_type,object_code,title,sort_order,status,created_revision_id,notes) VALUES (@k1_d,@k1_c,@k1_s,'FIGURE','K1_A2_F06','A2-6: Steigungsdreieck mit Δx und Δy. Autorenvorlage.',6,'REVIEW',@k1_r,'Bild aus aktualisierter Autorenvorlage') ON DUPLICATE KEY UPDATE section_id=VALUES(section_id),title=VALUES(title),created_revision_id=VALUES(created_revision_id);
INSERT INTO figures (object_id,figure_number,title,figure_type,caption,description,provenance_type,provenance_notes,rights_status,validation_status,notes) VALUES (@k1_o,'A1A2.6','A2-6: Steigungsdreieck mit Δx und Δy. Autorenvorlage.','DIAGRAM','A2-6: Steigungsdreieck mit Δx und Δy. Autorenvorlage.','Die neue Abbildung ergänzt das Steigungsdreieck. Für zwei Punkte der nicht senkrechten Geraden mit Δx ≠ 0 gilt a = Δy/Δx. Die aktuelle Autorenvorlage gibt hierfür näherungsweise a = 0,9 an und schreibt zunächst f(x) = 0,9x + b.','OWN','Aus der aktualisierten Vorlage A.2 lineareFunktion_erklärt(3).docx, Quelle SHA256 91283a6214ec3891f95ae71fd753adf57661cbb84a800abf732996e401e700b8','UNCLEAR','OPEN','Rechte der verwendeten grafischen Elemente gesondert prüfen') ON DUPLICATE KEY UPDATE title=VALUES(title),caption=VALUES(caption),description=VALUES(description),provenance_notes=VALUES(provenance_notes);
