-- Aktualisierter Nachimport Anlage 1A.2 / 1.A2; Revision 2026-11-09
-- Ausgangsdatei SHA256: 91283a6214ec3891f95ae71fd753adf57661cbb84a800abf732996e401e700b8
-- Word-Master SHA256: 918aef913ed44c2ae0b783146e7b766de1d9c977272c56056b4cbd2693ecb58b
-- Voraussetzung: frzk_dissertation-Schema und Kapitel 1 bereits importiert.
-- Nur Anlage 1A.2 und Verweis 1.1.2 werden ersetzt; keine anderen Kapitel oder Quellen.
-- Sicherheit: Vor Import Datenbanksicherung erstellen. Keine DELETEs fremder Abschnitte.
SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `frzk_dissertation`;
START TRANSACTION;
SET @k1_d := (SELECT id FROM dissertations WHERE project_code='FRZK' LIMIT 1);
SET @k1_c := (SELECT id FROM chapters WHERE dissertation_id=@k1_d AND chapter_number='1' LIMIT 1);
SET @k1_112 := (SELECT id FROM sections WHERE chapter_id=@k1_c AND section_number='1.1.2' LIMIT 1);
SET @k1_r := (SELECT id FROM revisions WHERE dissertation_id=@k1_d AND revision_code='K1_A2_UPDATE_V3_2026-11-09' LIMIT 1);
SET @k1_s := (SELECT id FROM sections WHERE chapter_id=@k1_c AND section_number='1.A2' LIMIT 1);
-- Alte Paragraphen ausschließlich der Anlage ersetzen (idempotent).
DELETE FROM paragraphs WHERE section_id=@k1_s;
-- Ref-Aktualisierung in 1.1.2; keine pauschale Änderung anderer Textstellen.
SET @k1_link_id := (SELECT id FROM paragraphs WHERE section_id=@k1_112 AND paragraph_label='K1-A2-VERWEIS' LIMIT 1);
UPDATE paragraphs SET paragraph_text='Anlage 1A.2 zeigt ergänzend zur hier beschriebenen Unterrichtsbeobachtung den schrittweisen Aufbau einer linearen Funktion. Die aktualisierte Vorlage führt die Bestimmung von Steigung und y-Achsenabschnitt bis zur Funktionsgleichung f(x) = 0,9x + 5,5 fort. Die Rückprüfung wird als methodische Ergänzung erläutert; ein empirischer Lernerfolg ist damit nicht nachgewiesen.',content_sha256='c9260c2e2ef377c03b7e0dcac423bc257b837d54fb6dba5113c0d6e32e319993',created_revision_id=@k1_r WHERE id=@k1_link_id;
SET @k1_next := (SELECT COALESCE(MAX(paragraph_index),0)+1 FROM paragraphs WHERE section_id=@k1_112);
SET @k1_oldref_start := 'Anlage 1A.2 zeigt ergänzend zur hier beschriebenen Unterrichtsbeobachtung';
UPDATE sections SET body_text = CASE WHEN LOCATE(@k1_oldref_start,COALESCE(body_text,''))>0 THEN CONCAT(SUBSTRING(COALESCE(body_text,''),1,LOCATE(@k1_oldref_start,COALESCE(body_text,''))-1),'Anlage 1A.2 zeigt ergänzend zur hier beschriebenen Unterrichtsbeobachtung den schrittweisen Aufbau einer linearen Funktion. Die aktualisierte Vorlage führt die Bestimmung von Steigung und y-Achsenabschnitt bis zur Funktionsgleichung f(x) = 0,9x + 5,5 fort. Die Rückprüfung wird als methodische Ergänzung erläutert; ein empirischer Lernerfolg ist damit nicht nachgewiesen.') ELSE CONCAT(COALESCE(body_text,''),'\n\n','Anlage 1A.2 zeigt ergänzend zur hier beschriebenen Unterrichtsbeobachtung den schrittweisen Aufbau einer linearen Funktion. Die aktualisierte Vorlage führt die Bestimmung von Steigung und y-Achsenabschnitt bis zur Funktionsgleichung f(x) = 0,9x + 5,5 fort. Die Rückprüfung wird als methodische Ergänzung erläutert; ein empirischer Lernerfolg ist damit nicht nachgewiesen.') END, current_revision_id=@k1_r WHERE id=@k1_112 AND (LOCATE(@k1_oldref_start,COALESCE(body_text,''))>0 OR LOCATE('Anlage 1A.2',COALESCE(body_text,''))=0);
UPDATE sections SET content_sha256=SHA2(COALESCE(body_text,''),256) WHERE id=@k1_112;
-- Kapitelgesamttext: bekannte A2-Überschrift identifizieren und blockweise ersetzen; kein anderer Abschnitt wird verkürzt.
SET @k1_old_h := 'Anlage 1A.2 – Iterativer Aufbau einer linearen Funktion (aktualisierte Autorenvorlage)';
SET @k1_prev_h := 'Anlage 1A.2 – Schrittweiser Aufbau und iterative Prüfung einer linearen Funktion';
SET @k1_start := LOCATE(@k1_old_h, COALESCE((SELECT body_text FROM chapters WHERE id=@k1_c),''));
SET @k1_start := IF(@k1_start>0,@k1_start,LOCATE(@k1_prev_h,COALESCE((SELECT body_text FROM chapters WHERE id=@k1_c),''))); 
SET @k1_next_h := IF(@k1_start>0,LOCATE('\n\nAnlage 1B',COALESCE((SELECT body_text FROM chapters WHERE id=@k1_c),''),@k1_start),0);
UPDATE chapters SET body_text=CONCAT(SUBSTRING(body_text,1,@k1_start-1),'Anlage 1A.2 – Iterativer Aufbau einer linearen Funktion (aktualisierte Autorenvorlage)\nDie aktualisierte Autorenvorlage „A.2 lineareFunktion_erklärt(3).docx“ dokumentiert in sieben aufeinander aufbauenden Grafiken den schrittweisen Zugang zu einer linearen Funktion. Sie ergänzt das Unterrichtsbeispiel aus Abschnitt 1.1.2, ohne eine standardisiert erhobene Lernwirkung zu behaupten. Die grafisch erläuterten Parameter a = 0,9 und b = 5,5 sind Angaben der überarbeiteten Vorlage; die angegebenen Zahlen sind nicht als vermessene Originaldaten einer Schülerbearbeitung belegt. Die neue Erläuterung der Parameter a und b ist Bestandteil der Autorenvorlage. Die nachfolgende Prüfschleife ist eine methodische Erläuterung, keine aus den Bildern belegte Beobachtung eines Rücksprungs.\n\nSchritt 1 – Eigenen Standpunkt markieren\n\nAusgangsimpuls: „Markiere Deinen eigenen Standpunkt“. Das zunächst isolierte Zeichen steht für eine subjektive Ausgangsorientierung. Es ist keine mathematische Definition des Koordinatenursprungs.\n\nA2-1: Ausgangsposition vor dem Aufbau des Bezugssystems. Autorenvorlage.\n\nSchritt 2 – Eine Gerade als Gegenstand darstellen\n\nAusgangsimpuls: „Füge ein Abbild einer linearen Funktion hinzu“. Die Gerade wird sichtbar; ihre Lage, Steigung und ihr Achsenabschnitt sind damit noch nicht numerisch festgelegt.\n\nA2-2: Gerade und markierter Standpunkt. Autorenvorlage.\n\nSchritt 3 – Koordinatensystem hinzufügen\n\nAusgangsimpuls: „Füge ein Bezugssystem hinzu“. Achsen erlauben es, die Lage der Geraden auf eine definierte Darstellung zu beziehen.\n\nA2-3: Ergänzte Koordinatenachsen. Autorenvorlage.\n\nSchritt 4 – Größen den Achsen zuordnen\n\nAusgangsimpuls: „Welche Größen wollen wir für die senkrechten und waagerechten Werte verwenden (x,y)?“ Die horizontale Achse wird mit x, die vertikale mit y bezeichnet. x steht als Eingangsgröße, y als zugeordneter Funktionswert.\n\nA2-4: Bezeichnete x- und y-Achse. Autorenvorlage.\n\nSchritt 5 – Definitionsbereich und Skalierung klären\n\nAusgangsimpuls: „Um die Funktion beschreiben zu können, benötigen wir einen …-Bereich“. Der Definitionsbereich legt zulässige x-Werte fest; Maßstab und Einheiten werden für ein Ablesen zusätzlich benötigt. Die Vorlage wählt gleiche Achsenmaßstäbe. Diese Wahl ist praktisch, aber nicht erforderlich, damit ein Koordinatensystem mathematisch gültig ist.\n\nA2-5: Koordinatensystem mit Skalierung. Autorenvorlage; EMF für die Word-Fassung in PNG übertragen.\n\nSchritt 6 – Die Steigung bestimmen\n\nDie neue Abbildung ergänzt das Steigungsdreieck. Für zwei Punkte der nicht senkrechten Geraden mit Δx ≠ 0 gilt a = Δy/Δx. Die aktuelle Autorenvorlage gibt hierfür näherungsweise a = 0,9 an und schreibt zunächst f(x) = 0,9x + b.\n\nSteigungsregel: a = Δy / Δx, wobei Δx ≠ 0.  Ergebnis der Autorenvorlage: a ≈ 0,9.\n\nWord-LaTeX: a=\\frac{\\Delta y}{\\Delta x},\\quad a\\approx 0{,}9\n\nA2-6: Steigungsdreieck mit Δx und Δy. Autorenvorlage.\n\nSchritt 7 – Den y-Achsenabschnitt bestimmen\n\nDer Schnittpunkt der Geraden mit der y-Achse wird als b = f(0) bezeichnet. Die neue Autorenvorlage gibt b = 5,5 an. Zusammen mit a = 0,9 ergibt sich f(x) = 0,9x + 5,5. Dies ist die in der Vorlage verwendete lineare beziehungsweise affine Funktionsdarstellung.\n\nAllgemeine Form: f(x) = ax + b.  Beispiel der Autorenvorlage: f(x) = 0,9x + 5,5.\n\nWord-LaTeX: f(x)=ax+b,\\quad f(x)=0{,}9x+5{,}5\n\nA2-7: y-Achsenabschnitt b und Steigungsdreieck. Autorenvorlage.\n\nErgänzende Erläuterung der Funktionsparameter (neue Autorenvorlage)\n\nDie Funktionsgleichung f(x)=ax+b beschreibt eine Gerade; die Parameter a und b bestimmen ihre Form und Lage.\n\nHier sind die beiden mathematischen Bausteine kurz zusammengefasst:\n\nDer Anstieg / die Steigung (a): Positives a bedeutet eine steigende, negatives a eine fallende Gerade; bei a=0 verläuft sie waagerecht.\n\nDer y-Achsenabschnitt (b): Die Gerade schneidet die vertikale y-Achse im Punkt (0,b); b beschreibt ihre vertikale Lage beziehungsweise Verschiebung.\n\nSchritt 8 – Eindeutigkeit und Geltungsbereich prüfen\n\nDie Vorlage spricht von „eineindeutiger Zuordnung“. Für den Funktionsbegriff muss jedem x des festgelegten Definitionsbereichs genau ein y-Wert zugeordnet sein. Eine allgemeine Umkehr-Eindeutigkeit ist nicht erforderlich. Bei der hier angegebenen Steigung a = 0,9 ist die konkret dargestellte Funktion auf ℝ allerdings streng monoton und damit injektiv. Die beiden Aussagen sind zu unterscheiden.\n\nSchritt 9 – Iterative Rückprüfung (methodische Ergänzung)\n\nBei Widersprüchen oder fehlenden Angaben kann zu einem früheren Bearbeitungsschritt zurückgekehrt werden: Sind Achsen und Einheiten festgelegt? Ist der Definitionsbereich benannt? Passen a = Δy/Δx und b = f(0) zur Zeichnung? Als Kontrollbeispiel liefert die Funktionsgleichung f(0) = 5,5 und f(1) − f(0) = 0,9. Wenn eine Prüfung misslingt, werden Annahme oder Darstellung angepasst und erneut überprüft. Die aktualisierten sieben Originalgrafiken zeigen den Aufbau; einen tatsächlichen Rücksprung oder Lernerfolg dokumentieren sie nicht.\n\nWissenschaftliche Einordnung. Die Anlage illustriert den methodischen FRZK-Ansatz als strukturierte, potenziell wiederholbare Problemerschließung. Das Verfahren ist hier ohne FRZK-spezifische Grenzwertzeichen und Vektoroperatoren anwendbar. Die in der Vorlage genannten Zahlenwerte sind als grafische Beispielparameter zu behandeln; ihre unabhängige Kalibrierung und die empirische Wirksamkeit gehören nicht zum Nachweisumfang dieser Anlage.',IF(@k1_next_h>0,SUBSTRING(body_text,@k1_next_h),'')) WHERE id=@k1_c AND @k1_start>0;
UPDATE chapters SET body_text=CONCAT(COALESCE(body_text,''),'\n\n','Anlage 1A.2 – Iterativer Aufbau einer linearen Funktion (aktualisierte Autorenvorlage)\nDie aktualisierte Autorenvorlage „A.2 lineareFunktion_erklärt(3).docx“ dokumentiert in sieben aufeinander aufbauenden Grafiken den schrittweisen Zugang zu einer linearen Funktion. Sie ergänzt das Unterrichtsbeispiel aus Abschnitt 1.1.2, ohne eine standardisiert erhobene Lernwirkung zu behaupten. Die grafisch erläuterten Parameter a = 0,9 und b = 5,5 sind Angaben der überarbeiteten Vorlage; die angegebenen Zahlen sind nicht als vermessene Originaldaten einer Schülerbearbeitung belegt. Die neue Erläuterung der Parameter a und b ist Bestandteil der Autorenvorlage. Die nachfolgende Prüfschleife ist eine methodische Erläuterung, keine aus den Bildern belegte Beobachtung eines Rücksprungs.\n\nSchritt 1 – Eigenen Standpunkt markieren\n\nAusgangsimpuls: „Markiere Deinen eigenen Standpunkt“. Das zunächst isolierte Zeichen steht für eine subjektive Ausgangsorientierung. Es ist keine mathematische Definition des Koordinatenursprungs.\n\nA2-1: Ausgangsposition vor dem Aufbau des Bezugssystems. Autorenvorlage.\n\nSchritt 2 – Eine Gerade als Gegenstand darstellen\n\nAusgangsimpuls: „Füge ein Abbild einer linearen Funktion hinzu“. Die Gerade wird sichtbar; ihre Lage, Steigung und ihr Achsenabschnitt sind damit noch nicht numerisch festgelegt.\n\nA2-2: Gerade und markierter Standpunkt. Autorenvorlage.\n\nSchritt 3 – Koordinatensystem hinzufügen\n\nAusgangsimpuls: „Füge ein Bezugssystem hinzu“. Achsen erlauben es, die Lage der Geraden auf eine definierte Darstellung zu beziehen.\n\nA2-3: Ergänzte Koordinatenachsen. Autorenvorlage.\n\nSchritt 4 – Größen den Achsen zuordnen\n\nAusgangsimpuls: „Welche Größen wollen wir für die senkrechten und waagerechten Werte verwenden (x,y)?“ Die horizontale Achse wird mit x, die vertikale mit y bezeichnet. x steht als Eingangsgröße, y als zugeordneter Funktionswert.\n\nA2-4: Bezeichnete x- und y-Achse. Autorenvorlage.\n\nSchritt 5 – Definitionsbereich und Skalierung klären\n\nAusgangsimpuls: „Um die Funktion beschreiben zu können, benötigen wir einen …-Bereich“. Der Definitionsbereich legt zulässige x-Werte fest; Maßstab und Einheiten werden für ein Ablesen zusätzlich benötigt. Die Vorlage wählt gleiche Achsenmaßstäbe. Diese Wahl ist praktisch, aber nicht erforderlich, damit ein Koordinatensystem mathematisch gültig ist.\n\nA2-5: Koordinatensystem mit Skalierung. Autorenvorlage; EMF für die Word-Fassung in PNG übertragen.\n\nSchritt 6 – Die Steigung bestimmen\n\nDie neue Abbildung ergänzt das Steigungsdreieck. Für zwei Punkte der nicht senkrechten Geraden mit Δx ≠ 0 gilt a = Δy/Δx. Die aktuelle Autorenvorlage gibt hierfür näherungsweise a = 0,9 an und schreibt zunächst f(x) = 0,9x + b.\n\nSteigungsregel: a = Δy / Δx, wobei Δx ≠ 0.  Ergebnis der Autorenvorlage: a ≈ 0,9.\n\nWord-LaTeX: a=\\frac{\\Delta y}{\\Delta x},\\quad a\\approx 0{,}9\n\nA2-6: Steigungsdreieck mit Δx und Δy. Autorenvorlage.\n\nSchritt 7 – Den y-Achsenabschnitt bestimmen\n\nDer Schnittpunkt der Geraden mit der y-Achse wird als b = f(0) bezeichnet. Die neue Autorenvorlage gibt b = 5,5 an. Zusammen mit a = 0,9 ergibt sich f(x) = 0,9x + 5,5. Dies ist die in der Vorlage verwendete lineare beziehungsweise affine Funktionsdarstellung.\n\nAllgemeine Form: f(x) = ax + b.  Beispiel der Autorenvorlage: f(x) = 0,9x + 5,5.\n\nWord-LaTeX: f(x)=ax+b,\\quad f(x)=0{,}9x+5{,}5\n\nA2-7: y-Achsenabschnitt b und Steigungsdreieck. Autorenvorlage.\n\nErgänzende Erläuterung der Funktionsparameter (neue Autorenvorlage)\n\nDie Funktionsgleichung f(x)=ax+b beschreibt eine Gerade; die Parameter a und b bestimmen ihre Form und Lage.\n\nHier sind die beiden mathematischen Bausteine kurz zusammengefasst:\n\nDer Anstieg / die Steigung (a): Positives a bedeutet eine steigende, negatives a eine fallende Gerade; bei a=0 verläuft sie waagerecht.\n\nDer y-Achsenabschnitt (b): Die Gerade schneidet die vertikale y-Achse im Punkt (0,b); b beschreibt ihre vertikale Lage beziehungsweise Verschiebung.\n\nSchritt 8 – Eindeutigkeit und Geltungsbereich prüfen\n\nDie Vorlage spricht von „eineindeutiger Zuordnung“. Für den Funktionsbegriff muss jedem x des festgelegten Definitionsbereichs genau ein y-Wert zugeordnet sein. Eine allgemeine Umkehr-Eindeutigkeit ist nicht erforderlich. Bei der hier angegebenen Steigung a = 0,9 ist die konkret dargestellte Funktion auf ℝ allerdings streng monoton und damit injektiv. Die beiden Aussagen sind zu unterscheiden.\n\nSchritt 9 – Iterative Rückprüfung (methodische Ergänzung)\n\nBei Widersprüchen oder fehlenden Angaben kann zu einem früheren Bearbeitungsschritt zurückgekehrt werden: Sind Achsen und Einheiten festgelegt? Ist der Definitionsbereich benannt? Passen a = Δy/Δx und b = f(0) zur Zeichnung? Als Kontrollbeispiel liefert die Funktionsgleichung f(0) = 5,5 und f(1) − f(0) = 0,9. Wenn eine Prüfung misslingt, werden Annahme oder Darstellung angepasst und erneut überprüft. Die aktualisierten sieben Originalgrafiken zeigen den Aufbau; einen tatsächlichen Rücksprung oder Lernerfolg dokumentieren sie nicht.\n\nWissenschaftliche Einordnung. Die Anlage illustriert den methodischen FRZK-Ansatz als strukturierte, potenziell wiederholbare Problemerschließung. Das Verfahren ist hier ohne FRZK-spezifische Grenzwertzeichen und Vektoroperatoren anwendbar. Die in der Vorlage genannten Zahlenwerte sind als grafische Beispielparameter zu behandeln; ihre unabhängige Kalibrierung und die empirische Wirksamkeit gehören nicht zum Nachweisumfang dieser Anlage.') WHERE id=@k1_c AND @k1_start=0;
UPDATE chapters SET current_revision_id=@k1_r WHERE id=@k1_c;
